#!/usr/bin/env node
/**
 * Generic CDP probe: navigate to a URL, wait, evaluate an expression, print JSON.
 *   node /tmp/probe-eval.mjs <url> '<js expression>' [width] [height] [waitMs]
 */
import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const url = process.argv[2] ?? 'http://127.0.0.1:8787/';
const expression = process.argv[3] ?? 'document.title';
const width = Number(process.argv[4] ?? 1440);
const height = Number(process.argv[5] ?? 1000);
const wait = Number(process.argv[6] ?? 6000);
const port = 9412;
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-eval-'));
const child = spawn('/usr/bin/google-chrome', [
  '--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`,
  '--no-sandbox', '--disable-gpu', '--hide-scrollbars', `--window-size=${width},${height}`, 'about:blank',
], { stdio: ['ignore', 'ignore', 'ignore'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) {
  for (let i = 0; i < 60; i += 1) {
    try { const r = await fetch(`http://127.0.0.1:${port}${p}`); if (r.ok) return r.json(); } catch {}
    await sleep(250);
  }
  throw new Error('no CDP');
}
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
const logs = [];
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
  else if (d.method === 'Runtime.exceptionThrown' || d.method === 'Log.entryAdded') logs.push(d.params?.exceptionDetails?.text ?? d.params?.entry?.text);
};
const send = (method, params = {}) => new Promise((res) => { const mid = ++id; pending.set(mid, res); ws.send(JSON.stringify({ id: mid, method, params })); });
await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: width < 500, screenWidth: width, screenHeight: height });
await send('Page.navigate', { url });
await sleep(wait);
const res = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
console.log(JSON.stringify({ value: res.result?.result?.value, exception: res.result?.exceptionDetails?.text, logs }, null, 1));
child.kill('SIGKILL');
ws.close();
process.exit(0);

