const TYPE_LABELS = {
  map: 'Einzelkarte',
  atlas: 'Atlas / Kartenwerk',
  sheet: 'Kartenblatt',
  overlay: 'Georeferenzierte Ebene',
};

const SCALE_MAX = 1000; // slider resolution for the year range

/** Default width of one histogram bin, in years. */
export const HISTOGRAM_BIN_YEARS = 10;

/** Year -> the start of the decade (or `bin`-year period) it belongs to. */
export const decadeOf = (year, bin = HISTOGRAM_BIN_YEARS) => Math.floor(Number(year) / bin) * bin;

/**
 * The decades the year axis of the data spans: one `{ start, end }` per bin,
 * in order, from the decade of `years.min` to the decade of `years.max`.
 * Pure, so the axis (and every label built from it) is unit-tested.
 */
export function decadeAxis(years, bin = HISTOGRAM_BIN_YEARS) {
  const min = Number(years?.min);
  const max = Number(years?.max);
  if (!Number.isFinite(min) || !Number.isFinite(max) || max < min) return [];
  const bins = [];
  for (let start = decadeOf(min, bin); start <= decadeOf(max, bin); start += bin) {
    bins.push({ start, end: start + bin - 1 });
  }
  return bins;
}

/**
 * How many records fall into each decade of the axis. The publication year is
 * clamped into `[years.min, years.max]` — the same rule the axis itself uses, so
 * a record dated 2021 lands in the last bin instead of a bin the axis drops.
 * Records without a year are counted nowhere (they are listed, but not drawn).
 * Returned in axis order, so `decadeCounts(...)[i]` belongs to `decadeAxis(...)[i]`.
 */
export function decadeCounts(records, years, bin = HISTOGRAM_BIN_YEARS) {
  const axis = decadeAxis(years, bin);
  const counts = axis.map((slot) => ({ ...slot, count: 0 }));
  if (axis.length === 0) return counts;
  const index = new Map(counts.map((slot, i) => [slot.start, i]));
  for (const record of records ?? []) {
    const year = Number.isFinite(record?.yearStart) ? record.yearStart : record?.yearEnd;
    if (!Number.isFinite(year)) continue;
    const clamped = Math.max(Number(years.min), Math.min(Number(years.max), Number(year)));
    const slot = index.get(decadeOf(clamped, bin));
    if (slot !== undefined) counts[slot].count += 1;
  }
  return counts;
}

/**
 * Extend (or shrink) a year range by one axis step, for the histogram's
 * keyboard route:
 *
 *   'right' -> the end grows to the end of the next decade,
 *   'left'  -> the start moves to the start of the previous decade,
 *   'start' -> the start jumps to the first year of the data,
 *   'end'   -> the end jumps to the last year of the data.
 *
 * Always clamped into `[years.min, years.max]`, so a hand-written URL or a
 * key held down can never leave the data's own axis. Pure and unit-tested.
 */
export function extendRange(range, direction, years, bin = HISTOGRAM_BIN_YEARS) {
  const min = Number(years?.min);
  const max = Number(years?.max);
  const clamp = (value) => Math.max(min, Math.min(max, Number(value)));
  let from = Number.isFinite(Number(range?.from)) ? clamp(range.from) : min;
  let to = Number.isFinite(Number(range?.to)) ? clamp(range.to) : max;
  if (direction === 'right') to = Math.min(max, decadeOf(to, bin) + 2 * bin - 1);
  else if (direction === 'left') from = Math.max(min, decadeOf(from, bin) - bin);
  else if (direction === 'start') from = min;
  else if (direction === 'end') to = max;
  if (from > to) to = from;
  return { from, to };
}

