const histogramEl = qs('#year-histogram');
const histogramScale = qs('#year-histogram-scale');
const BIN_YEARS = HISTOGRAM_BIN_YEARS;

/** One bin per decade the publication years of the seed span. */
const histogramAxis = decadeAxis(years, BIN_YEARS);

/**
 * The records the histogram bars describe: everything the other filters leave
 * except the time range itself — the same rule the facet counts follow, so the
 * chart answers “where in time do *my* current filters live?” instead of
 * always showing the whole corpus.
 */
function scopeWithoutTime(state) {
  const point = parsePoint(state.at);
  return records.filter(
    (record) =>
      matchesQuery(record, state.q) &&
      (!state.provider || record.providerId === state.provider) &&
      (!state.type || record.type === state.type) &&
      (!state.collection || record.collection === state.collection) &&
      (!state.viewport || state.viewport !== '1') &&
      (!point || coversPoint(record, point.lat, point.lon)),
  );
}

function buildHistogram() {
  if (!histogramEl) return;
  histogramEl.replaceChildren(
    ...histogramAxis.map((bin) => {
      const from = Math.max(years.min, bin.start);
      const to = Math.min(years.max, bin.end);
      const label = `${bin.start}–${bin.end}: 0 Datensätze`;
      return el(
        'button',
        {
          class: 'zh-histogram__bin is-empty',
          type: 'button',
          tabindex: '-1',
          'data-start': bin.start,
          'data-end': bin.end,
          'data-count': 0,
          title: label,
          'aria-label': `${label}. Zeitraum ${from}–${to} filtern.`,
          onclick: () => ctx.store.update({ from, to }),
        },
        [el('span', { class: 'zh-histogram__bar', style: 'height:2%' })],
      );
    }),
  );
  histogramScale?.replaceChildren(el('span', { text: String(years.min) }), el('span', { text: String(years.max) }));
  const first = histogramEl.querySelector('button');
  if (first) first.tabIndex = 0;
}

/**
 * Update the bars for the current scope and mark the decades inside the range.
 * The buttons are never rebuilt (that would drop keyboard focus); only their
 * count, label, height and state change.
 */
function updateHistogram(state) {
  if (!histogramEl) return;
  const counts = decadeCounts(scopeWithoutTime(state), years, BIN_YEARS);
  const busiest = Math.max(1, ...counts.map((bin) => bin.count));
  const buttons = [...histogramEl.querySelectorAll('button')];
  buttons.forEach((button, index) => {
    const bin = counts[index];
    if (!bin) return;
    const from = Math.max(years.min, bin.start);
    const to = Math.min(years.max, bin.end);
    const label = `${bin.start}–${bin.end}: ${bin.count} ${bin.count === 1 ? 'Datensatz' : 'Datensätze'}`;
    button.dataset.count = String(bin.count);
    button.title = label;
    button.setAttribute('aria-label', `${label}. Zeitraum ${from}–${to} filtern.`);
    button.classList.toggle('is-empty', bin.count === 0);
    const bar = button.firstElementChild;
