  if (event.shiftKey && ['ArrowRight', 'ArrowLeft', 'Home', 'End'].includes(event.key)) {
    const direction = event.key === 'ArrowRight' ? 'right' : event.key === 'ArrowLeft' ? 'left' : event.key === 'Home' ? 'start' : 'end';
    const state = ctx.store.getState();
    const next = extendRange(state, direction, years, BIN_YEARS);
    if (next.from === state.from && next.to === state.to) return;
    event.preventDefault();
    ctx.store.update(next);
    if (liveEl) liveEl.textContent = `Zeitraum ${next.from}–${next.to}.`;
    return;
