/**
 * Decade histogram (maps-2): the bars describe the *current* filter scope
 * (everything except the time range itself) and the keyboard can build a range
 * out of whole decades. Both rules are pure functions in `results.js`, so they
 * are tested here without a DOM, a slider or a browser.
 */
import test from 'node:test';
import assert from 'node:assert/strict';

import { HISTOGRAM_BIN_YEARS, decadeAxis, decadeCounts, decadeOf, extendRange } from '../public/app/results.js';
import { filterRecords } from '../public/app/records.js';

const YEARS = { min: 1696, max: 2021 };

test('the axis spans one bin per decade the data touches', () => {
  const axis = decadeAxis(YEARS);
  assert.equal(axis[0].start, 1690, 'the first bin starts at the decade of the oldest year');
  assert.equal(axis[axis.length - 1].start, 2020, 'the last bin is the decade of the newest year');
  assert.ok(axis.every((bin, i) => bin.end === bin.start + HISTOGRAM_BIN_YEARS - 1), 'every bin is ten years wide');
  assert.ok(axis.every((bin, i) => i === 0 || bin.start === axis[i - 1].end + 1), 'bins are contiguous');
  assert.equal(axis.length, 34, '1690 … 2020');
  assert.deepEqual(decadeAxis({ min: 1800, max: 1799 }), [], 'impossible bounds produce no axis');
  assert.deepEqual(decadeAxis({}), []);
  assert.equal(decadeOf(1781), 1780);
  assert.equal(decadeOf(1800), 1800);
});

test('every record with a year is counted exactly once, in its own decade', () => {
  const records = [
    { id: 'a', yearStart: 1781 },
    { id: 'b', yearStart: 1789 },
    { id: 'c', yearStart: 1790 },
    { id: 'd', yearStart: 1690, yearEnd: 1699 }, // before the axis start -> clamped to the first bin
    { id: 'e', yearStart: 2025 }, // after the axis end -> clamped to the last bin
    { id: 'f', yearStart: null, yearEnd: 1815 }, // no yearStart: the depicted end year is used
    { id: 'g', yearStart: null, yearEnd: null }, // no year at all: counted nowhere
  ];
  const counts = decadeCounts(records, YEARS);
  const byStart = new Map(counts.map((bin) => [bin.start, bin.count]));
  assert.equal(byStart.get(1780), 2);
  assert.equal(byStart.get(1790), 1);
  assert.equal(byStart.get(1690), 1, 'a year before the data is clamped, not dropped');
  assert.equal(byStart.get(2020), 1, 'a year after the data is clamped, not dropped');
  assert.equal(byStart.get(1810), 1);
  const total = counts.reduce((sum, bin) => sum + bin.count, 0);
  assert.equal(total, 6, 'six of the seven records state

